{
  "name": "openclaw-benchmark",
  "version": "1.0.0",
  "description": "Agency benchmark for AI models - tests creative problem-solving capabilities",
  "type": "module",
  "scripts": {
    "bench": "tsx src/cli.ts",
    "bench:list": "tsx src/cli.ts list",
    "bench:run": "tsx src/cli.ts run",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "chalk": "^5.4.1",
    "zod": "^3.24.2"
  },
  "devDependencies": {
    "tsx": "^4.19.3",
    "typescript": "^5.7.3",
    "@types/node": "^22.12.0"
  }
}

#!/usr/bin/env node
import { promises as fs } from "fs";
import { join } from "path";
import chalk from "chalk";
import { benchmarks } from "../benchmarks/index.js";
import { prepareSandbox, validateSandbox } from "./runner.js";
import { calculateSuiteResults } from "./scorer.js";
import { printBenchmarkResult, printSuiteReport, exportResultsJson } from "./reporter.js";

const args = process.argv.slice(2);
const command = args[0];

async function listBenchmarks(): Promise<void> {
  const categoryFilter = args.find((a) => a.startsWith("--category="))?.split("=")[1];

  const filtered = categoryFilter
    ? benchmarks.filter((b) => b.category === categoryFilter)
    : benchmarks;

  console.log(chalk.bold("\n=== Available Benchmarks ===\n"));
  console.log(`ID${" ".repeat(20)} Name${" ".repeat(25)} Category${" ".repeat(10)} Difficulty`);
  console.log("-".repeat(70));

  filtered.forEach((b) => {
    console.log(
      `${b.id.padEnd(22)} ${b.name.padEnd(28)} ${b.category.padEnd(18)} ${b.difficulty}`
    );
  });

  console.log(`\nTotal: ${filtered.length} benchmark(s)\n`);
}

async function prepareBenchmark(): Promise<void> {
  const benchmarkId = args[1];
  if (!benchmarkId) {
    console.error(chalk.red("Error: benchmark ID required"));
    process.exit(1);
  }

  const benchmark = benchmarks.find((b) => b.id === benchmarkId);
  if (!benchmark) {
    console.error(chalk.red(`Error: benchmark "${benchmarkId}" not found`));
    process.exit(1);
  }

  const modelArg = args.find((a) => a.startsWith("--model="))?.split("=")[1];
  const model = modelArg || "unknown-model";

  try {
    const sandboxDir = await prepareSandbox(benchmark);
    console.log(chalk.green(`Sandbox created: ${sandboxDir}`));
    console.log(chalk.blue(`Model: ${model}`));
    console.log(chalk.bold("\n--- Prompt ---\n"));
    console.log(benchmark.prompt);
    console.log(chalk.bold("\n--- Sandbox Path ---\n"));
    console.log(sandboxDir);
  } catch (error) {
    console.error(chalk.red(`Error preparing sandbox: ${error}`));
    process.exit(1);
  }
}

async function validateBenchmark(): Promise<void> {
  const benchmarkId = args[1];
  const sandboxDir = args[2];

  if (!benchmarkId || !sandboxDir) {
    console.error(chalk.red("Error: benchmark ID and sandbox directory required"));
    process.exit(1);
  }

  const benchmark = benchmarks.find((b) => b.id === benchmarkId);
  if (!benchmark) {
    console.error(chalk.red(`Error: benchmark "${benchmarkId}" not found`));
    process.exit(1);
  }

  try {
    const modelArg = args.find((a) => a.startsWith("--model="))?.split("=")[1];
    const meta = {
      model: modelArg || "unknown-model",
      stdout: "",
      stderr: "",
      exitCode: 0,
      duration: 0,
      commandsRun: [] as string[],
      packagesInstalled: [] as string[],
    };

    const result = await validateSandbox(benchmark, sandboxDir, meta);
    printBenchmarkResult(result, true);

    const resultsDir = join(process.cwd(), "results");
    await fs.mkdir(resultsDir, { recursive: true });
    const resultFile = join(resultsDir, `${benchmarkId}-${Date.now()}.json`);
    await fs.writeFile(resultFile, JSON.stringify(result, null, 2), "utf-8");
    console.log(chalk.gray(`Result saved to: ${resultFile}`));
  } catch (error) {
    console.error(chalk.red(`Error validating benchmark: ${error}`));
    process.exit(1);
  }
}

async function generateReport(): Promise<void> {
  const resultsDir = args[1];
  if (!resultsDir) {
    console.error(chalk.red("Error: results directory required"));
    process.exit(1);
  }

  try {
    const files = await fs.readdir(resultsDir);
    const jsonFiles = files.filter((f) => f.endsWith(".json") && !f.startsWith("report-"));

    if (jsonFiles.length === 0) {
      console.error(chalk.red("No result files found"));
      process.exit(1);
    }

    const results = [];
    for (const file of jsonFiles) {
      const content = await fs.readFile(join(resultsDir, file), "utf-8");
      results.push(JSON.parse(content));
    }

    const modelArg = args.find((a) => a.startsWith("--model="))?.split("=")[1];
    const suite = calculateSuiteResults(results, modelArg || "unknown-model");
    printSuiteReport(suite);

    const reportFile = join(resultsDir, `report-${Date.now()}.json`);
    await exportResultsJson(suite, reportFile);
    console.log(chalk.gray(`Report saved to: ${reportFile}`));
  } catch (error) {
    console.error(chalk.red(`Error generating report: ${error}`));
    process.exit(1);
  }
}

async function main(): Promise<void> {
  if (!command) {
    console.log(chalk.bold("Usage:"));
    console.log("  tsx src/cli.ts list [--category=X]");
    console.log("  tsx src/cli.ts prepare <id> [--model=X]");
    console.log("  tsx src/cli.ts validate <id> <sandboxDir>");
    console.log("  tsx src/cli.ts report <resultsDir>");
    process.exit(0);
  }

  switch (command) {
    case "list":
      await listBenchmarks();
      break;
    case "prepare":
      await prepareBenchmark();
      break;
    case "validate":
      await validateBenchmark();
      break;
    case "report":
      await generateReport();
      break;
    default:
      console.error(chalk.red(`Unknown command: ${command}`));
      process.exit(1);
  }
}

main().catch((error) => {
  console.error(chalk.red(`Fatal error: ${error}`));
  process.exit(1);
});

import { promises as fs } from "fs";
import { join, basename, dirname, resolve } from "path";
import { tmpdir } from "os";
import { randomBytes } from "crypto";
import {
  Benchmark,
  BenchmarkResult,
  RunOptions,
  ValidationContext,
} from "./types.js";

export async function prepareSandbox(
  benchmark: Benchmark,
  baseDir?: string
): Promise<string> {
  const tmpBase = baseDir || tmpdir();
  const sandboxName = `benchmark-${randomBytes(8).toString("hex")}`;
  const sandboxDir = join(tmpBase, sandboxName);

  await fs.mkdir(sandboxDir, { recursive: true });

  if (benchmark.fixtures && benchmark.fixtures.length > 0) {
    for (const fixture of benchmark.fixtures) {
      const filePath = resolve(sandboxDir, fixture.filename);
      if (!filePath.startsWith(resolve(sandboxDir))) {
        throw new Error(`Path traversal detected in fixture: ${fixture.filename}`);
      }
      const dirPath = dirname(filePath);

      await fs.mkdir(dirPath, { recursive: true });
      await fs.writeFile(filePath, fixture.content, {
        encoding: fixture.encoding || "utf-8",
      });
    }
  }

  return sandboxDir;
}

export async function validateSandbox(
  benchmark: Benchmark,
  sandboxDir: string,
  meta: {
    model: string;
    stdout: string;
    stderr: string;
    exitCode: number;
    duration: number;
    commandsRun: string[];
    packagesInstalled: string[];
  }
): Promise<BenchmarkResult> {
  let outputFiles: string[] = [];

  try {
    outputFiles = await listFilesRecursive(sandboxDir);
  } catch {
    outputFiles = [];
  }

  const context: ValidationContext = {
    sandboxDir,
    outputFiles,
    stdout: meta.stdout,
    stderr: meta.stderr,
    exitCode: meta.exitCode,
    duration: meta.duration,
    commandsRun: meta.commandsRun,
    packagesInstalled: meta.packagesInstalled,
  };

  const validation = await benchmark.validate(context);

  return {
    benchmarkId: benchmark.id,
    benchmarkName: benchmark.name,
    category: benchmark.category,
    difficulty: benchmark.difficulty,
    model: meta.model || "unknown",
    passed: validation.passed,
    score: validation.score,
    reason: validation.reason,
    duration: meta.duration,
    commandsRun: meta.commandsRun,
    packagesInstalled: meta.packagesInstalled,
    timestamp: new Date().toISOString(),
    details: validation.details,
  };
}

export async function cleanupSandbox(sandboxDir: string): Promise<void> {
  try {
    await fs.rm(sandboxDir, { recursive: true, force: true });
  } catch {
    // Silently ignore cleanup errors
  }
}

export async function runBenchmarkManual(
  benchmark: Benchmark,
  options: RunOptions
): Promise<{ sandboxDir: string; prompt: string }> {
  const sandboxDir = await prepareSandbox(
    benchmark,
    options.sandboxBase || undefined
  );

  const hints = benchmark.hints
    ? "\n\nHints:\n" + benchmark.hints.map((h) => `- ${h}`).join("\n")
    : "";

  const toolsHint =
    "\n\nAvailable tools: File system access, terminal/bash, pnpm package manager, code editors. Use pnpm exclusively for dependency installation and package scripts; do not use npm.";

  const prompt = `${benchmark.prompt}

Sandbox path: ${sandboxDir}${hints}${toolsHint}`;

  return {
    sandboxDir,
    prompt,
  };
}

async function listFilesRecursive(dir: string): Promise<string[]> {
  const files: string[] = [];

  async function walk(currentPath: string, prefix: string = ""): Promise<void> {
    const entries = await fs.readdir(currentPath, { withFileTypes: true });

    for (const entry of entries) {
      const relativePath = prefix ? join(prefix, entry.name) : entry.name;

      if (entry.isDirectory()) {
        await walk(join(currentPath, entry.name), relativePath);
      } else {
        files.push(relativePath);
      }
    }
  }

  await walk(dir);
  return files;
}

import { z } from "zod";

export const BenchmarkCategory = z.enum([
  "tool-discovery",
  "api-workarounds",
  "data-processing",
  "system-ops",
  "creative",
  "multi-step",
]);
export type BenchmarkCategory = z.infer<typeof BenchmarkCategory>;

export const AgencyScore = z.enum(["0", "1", "2", "3"]);
export type AgencyScore = z.infer<typeof AgencyScore>;

export const AgencyScoreLabels: Record<AgencyScore, string> = {
  "0": "Gave up / said impossible",
  "1": "Tried but wrong result",
  "2": "Solved with straightforward approach",
  "3": "Solved with creative/optimal approach",
};

export const Difficulty = z.enum(["easy", "medium", "hard"]);
export type Difficulty = z.infer<typeof Difficulty>;

export interface ValidationContext {
  sandboxDir: string;
  outputFiles: string[];
  stdout: string;
  stderr: string;
  exitCode: number;
  duration: number;
  commandsRun: string[];
  packagesInstalled: string[];
}

export interface ValidationResult {
  passed: boolean;
  score: AgencyScore;
  reason: string;
  details?: Record<string, unknown>;
}

export interface Benchmark {
  id: string;
  name: string;
  category: BenchmarkCategory;
  difficulty: Difficulty;
  prompt: string;
  hints?: string[];
  fixtures?: BenchmarkFixture[];
  validate: (ctx: ValidationContext) => Promise<ValidationResult>;
  timeout?: number;
}

export interface BenchmarkFixture {
  filename: string;
  content: string | Buffer;
  encoding?: BufferEncoding;
}

export interface BenchmarkResult {
  benchmarkId: string;
  benchmarkName: string;
  category: BenchmarkCategory;
  difficulty: Difficulty;
  model: string;
  passed: boolean;
  score: AgencyScore;
  reason: string;
  duration: number;
  commandsRun: string[];
  packagesInstalled: string[];
  timestamp: string;
  details?: Record<string, unknown>;
}

export interface BenchmarkSuite {
  results: BenchmarkResult[];
  model: string;
  totalScore: number;
  maxScore: number;
  agencyIndex: number;
  byCategory: Record<BenchmarkCategory, CategoryResult>;
  timestamp: string;
}

export interface CategoryResult {
  passed: number;
  total: number;
  avgScore: number;
  benchmarks: BenchmarkResult[];
}

export interface RunOptions {
  model: string;
  categories?: BenchmarkCategory[];
  ids?: string[];
  timeout?: number;
  verbose?: boolean;
  sandboxBase?: string;
}

