import {
  BenchmarkResult,
  BenchmarkSuite,
  BenchmarkCategory,
  CategoryResult,
} from "./types.js";

interface ModelComparison {
  ranking: Array<{ model: string; agencyIndex: number; totalScore: number }>;
  byCategory: Record<
    BenchmarkCategory,
    Array<{ model: string; avgScore: number; passed: number }>
  >;
}

export function calculateSuiteResults(
  results: BenchmarkResult[],
  model: string
): BenchmarkSuite {
  const byCategory: Record<BenchmarkCategory, CategoryResult> = {
    "tool-discovery": {
      passed: 0,
      total: 0,
      avgScore: 0,
      benchmarks: [],
    },
    "api-workarounds": {
      passed: 0,
      total: 0,
      avgScore: 0,
      benchmarks: [],
    },
    "data-processing": {
      passed: 0,
      total: 0,
      avgScore: 0,
      benchmarks: [],
    },
    "system-ops": {
      passed: 0,
      total: 0,
      avgScore: 0,
      benchmarks: [],
    },
    creative: {
      passed: 0,
      total: 0,
      avgScore: 0,
      benchmarks: [],
    },
    "multi-step": {
      passed: 0,
      total: 0,
      avgScore: 0,
      benchmarks: [],
    },
  };

  for (const result of results) {
    const category = byCategory[result.category];
    category.total += 1;
    if (result.passed) {
      category.passed += 1;
    }
    category.benchmarks.push(result);
  }

  let totalScore = 0;

  for (const category of Object.values(byCategory)) {
    if (category.total > 0) {
      const scores = category.benchmarks.map((b) => parseInt(b.score));
      category.avgScore = scores.reduce((a, b) => a + b, 0) / scores.length;
      totalScore += scores.reduce((a, b) => a + b, 0);
    }
  }

  const maxScore = results.length * 3;
  const agencyIndex = maxScore > 0 ? totalScore / maxScore : 0;

  return {
    results,
    model,
    totalScore,
    maxScore,
    agencyIndex,
    byCategory,
    timestamp: new Date().toISOString(),
  };
}

export function compareModels(suites: BenchmarkSuite[]): ModelComparison {
  const ranking = suites
    .map((suite) => ({
      model: suite.model,
      agencyIndex: suite.agencyIndex,
      totalScore: suite.totalScore,
    }))
    .sort((a, b) => b.agencyIndex - a.agencyIndex);

  const categories: BenchmarkCategory[] = [
    "tool-discovery",
    "api-workarounds",
    "data-processing",
    "system-ops",
    "creative",
    "multi-step",
  ];

  const byCategory: Record<
    BenchmarkCategory,
    Array<{ model: string; avgScore: number; passed: number }>
  > = {} as Record<
    BenchmarkCategory,
    Array<{ model: string; avgScore: number; passed: number }>
  >;

  for (const category of categories) {
    byCategory[category] = suites
      .map((suite) => ({
        model: suite.model,
        avgScore: suite.byCategory[category].avgScore,
        passed: suite.byCategory[category].passed,
      }))
      .sort((a, b) => b.avgScore - a.avgScore);
  }

  return {
    ranking,
    byCategory,
  };
}

import chalk from "chalk";
import { BenchmarkSuite, BenchmarkResult, AgencyScoreLabels, BenchmarkCategory } from "./types.js";
import { promises as fs } from "fs";

export interface ModelComparison {
  models: Array<{
    model: string;
    agencyIndex: number;
    totalScore: number;
    maxScore: number;
    results: BenchmarkResult[];
  }>;
  timestamp: string;
}

export function printBenchmarkResult(result: BenchmarkResult, verbose?: boolean): void {
  const statusLabel = result.passed ? chalk.green("PASS") : chalk.red("FAIL");
  const scoreColor = result.score === "3" ? chalk.cyan : result.score === "0" ? chalk.red : chalk.yellow;
  const scoreLabel = scoreColor(`${result.score}/3`);
  const categoryLabel = chalk.gray(`(${result.category})`);

  let line = `${statusLabel} ${scoreLabel} ${result.benchmarkName} ${categoryLabel} - ${result.reason}`;

  if (verbose) {
    line += ` [${result.duration}ms]`;
  }

  console.log(line);
}

export function printSuiteReport(suite: BenchmarkSuite): void {
  console.log(chalk.bold("\n=== Benchmark Suite Report ===\n"));
  console.log(chalk.blue(`Model: ${suite.model}`));
  console.log(chalk.blue(`Timestamp: ${suite.timestamp}`));

  console.log(chalk.bold("\n--- Results by Category ---\n"));

  const categories = Object.entries(suite.byCategory);
  let maxCategoryLength = 0;
  categories.forEach(([cat]) => {
    if (cat.length > maxCategoryLength) maxCategoryLength = cat.length;
  });

  categories.forEach(([category, result]) => {
    const percentage = ((result.avgScore / 3) * 100).toFixed(1);
    const passStatus = `${result.passed}/${result.total}`;
    const categoryPad = category.padEnd(maxCategoryLength);
    console.log(
      `  ${categoryPad}  ${passStatus.padEnd(8)}  avg: ${result.avgScore.toFixed(2)}/3 (${percentage}%)`
    );
  });

  console.log(chalk.bold("\n--- Overall Score ---\n"));
  const agencyPercentage = (suite.agencyIndex * 100).toFixed(1);
  console.log(`  Total Score: ${chalk.cyan(suite.totalScore.toString())} / ${suite.maxScore}`);
  console.log(`  Agency Index: ${chalk.cyan(agencyPercentage + "%")}`);

  const activeCategories = categories.filter(([, cat]) => cat.total > 0);
  if (activeCategories.length === 0) return;

  const bestCategory = activeCategories.reduce((best, [name, cat]) =>
    cat.avgScore > best[1].avgScore ? [name, cat] : best
  );
  const worstCategory = activeCategories.reduce((worst, [name, cat]) =>
    cat.avgScore < worst[1].avgScore ? [name, cat] : worst
  );

  console.log(chalk.bold("\n--- Highlights ---\n"));
  console.log(chalk.green(`  Best: ${bestCategory[0]} (${bestCategory[1].avgScore.toFixed(2)}/3)`));
  console.log(chalk.yellow(`  Worst: ${worstCategory[0]} (${worstCategory[1].avgScore.toFixed(2)}/3)`));
  console.log();
}

export function printComparisonReport(comparison: ModelComparison): void {
  console.log(chalk.bold("\n=== Model Comparison Report ===\n"));
  console.log(chalk.blue(`Timestamp: ${comparison.timestamp}`));

  const sorted = [...comparison.models].sort((a, b) => b.agencyIndex - a.agencyIndex);

  console.log(chalk.bold("\n--- Rankings ---\n"));
  sorted.forEach((model, idx) => {
    const rank = idx + 1;
    const agencyPercentage = (model.agencyIndex * 100).toFixed(1);
    const medal = rank === 1 ? "🥇" : rank === 2 ? "🥈" : rank === 3 ? "🥉" : "  ";
    console.log(
      `  #${rank} ${medal} ${chalk.cyan(model.model.padEnd(20))} ${agencyPercentage}% (${model.totalScore}/${model.maxScore})`
    );
  });

  console.log(chalk.bold("\n--- Per-Category Breakdown ---\n"));

  const categories: Set<BenchmarkCategory> = new Set();
  sorted.forEach((model) => {
    const categoryMap = new Map<BenchmarkCategory, { passed: number; total: number; avgScore: number }>();
    model.results.forEach((result) => {
      categories.add(result.category);
      const existing = categoryMap.get(result.category) || { passed: 0, total: 0, avgScore: 0 };
      categoryMap.set(result.category, {
        passed: existing.passed + (result.passed ? 1 : 0),
        total: existing.total + 1,
        avgScore: existing.avgScore + parseFloat(result.score),
      });
    });

    Array.from(categories).forEach((cat) => {
      const catData = categoryMap.get(cat);
      if (catData) {
        const avg = (catData.avgScore / catData.total).toFixed(2);
        const percentage = ((parseFloat(avg) / 3) * 100).toFixed(0);
        console.log(
          `  ${model.model.padEnd(15)} ${cat.padEnd(18)} ${catData.passed}/${catData.total} passed (avg: ${avg}/3, ${percentage}%)`
        );
      }
    });
    console.log();
  });
}

export async function exportResultsJson(suite: BenchmarkSuite, filepath: string): Promise<void> {
  const json = JSON.stringify(suite, null, 2);
  await fs.writeFile(filepath, json, "utf-8");
}

import { promises as fs } from "fs";
import { join, resolve } from "path";

function safePath(sandboxDir: string, filename: string): string {
  const resolved = resolve(sandboxDir, filename);
  if (!resolved.startsWith(resolve(sandboxDir))) {
    throw new Error(`Path traversal detected: ${filename}`);
  }
  return resolved;
}

export async function fileExists(
  sandboxDir: string,
  filename: string
): Promise<boolean> {
  try {
    await fs.access(safePath(sandboxDir, filename));
    return true;
  } catch {
    return false;
  }
}

export async function fileContains(
  sandboxDir: string,
  filename: string,
  content: string
): Promise<boolean> {
  try {
    const fileContent = await fs.readFile(safePath(sandboxDir, filename), "utf-8");
    return fileContent.includes(content);
  } catch {
    return false;
  }
}

export async function fileMatchesRegex(
  sandboxDir: string,
  filename: string,
  regex: RegExp
): Promise<boolean> {
  try {
    const fileContent = await fs.readFile(safePath(sandboxDir, filename), "utf-8");
    return regex.test(fileContent);
  } catch {
    return false;
  }
}

export async function fileSizeInRange(
  sandboxDir: string,
  filename: string,
  min: number,
  max: number
): Promise<boolean> {
  try {
    const stats = await fs.stat(safePath(sandboxDir, filename));
    return stats.size >= min && stats.size <= max;
  } catch {
    return false;
  }
}

export async function fileIsValidJson(
  sandboxDir: string,
  filename: string
): Promise<boolean> {
  try {
    const fileContent = await fs.readFile(safePath(sandboxDir, filename), "utf-8");
    JSON.parse(fileContent);
    return true;
  } catch {
    return false;
  }
}

export async function fileIsValidHtml(
  sandboxDir: string,
  filename: string
): Promise<boolean> {
  try {
    const fileContent = await fs.readFile(safePath(sandboxDir, filename), "utf-8");
    return /<[^>]+>/g.test(fileContent);
  } catch {
    return false;
  }
}

export async function fileHasExtension(
  sandboxDir: string,
  filename: string,
  ext: string
): Promise<boolean> {
  try {
    const file = safePath(sandboxDir, filename);
    return file.endsWith(ext);
  } catch {
    return false;
  }
}

export async function directoryHasFiles(
  sandboxDir: string,
  dir: string,
  minCount: number
): Promise<boolean> {
  try {
    const files = await fs.readdir(join(sandboxDir, dir));
    return files.length >= minCount;
  } catch {
    return false;
  }
}

export async function stdoutContains(
  stdout: string,
  content: string
): Promise<boolean> {
  return stdout.includes(content);
}

export async function stdoutMatchesRegex(
  stdout: string,
  regex: RegExp
): Promise<boolean> {
  return regex.test(stdout);
}

export async function commandWasUsed(
  commands: string[],
  toolName: string
): Promise<boolean> {
  return commands.some((cmd) => cmd.includes(toolName));
}

export async function packageWasInstalled(
  packages: string[],
  packageName: string
): Promise<boolean> {
  return packages.includes(packageName);
}

