Alice,alice@test.com,2024-02-20,92
Charlie,charlie@test.com,2024-01-12,78
Bob,bob@test.com,2024-03-05,95
Diana,diana@test.com,2024-01-08,88`,
    },
  ],
  validate: async (ctx: ValidationContext): Promise<ValidationResult> => {
