    ram: { total_bytes: Number(ram.stdout.trim() || 0) },
    disk: { available_kb: availableKb },
    node: nodeVersion.stdout.trim(),
    pnpm: pnpmVersion.stdout.trim(),
    python: python.stdout.trim() || python.stderr.trim() || null,
