  console.error(String(error));
  const width = 16;
  const height = Math.max(1, Math.ceil(buf.length / (width * 3)));
  const padded = Buffer.alloc(width * height * 3);
  buf.copy(padded);
  raw = await sharp(padded, { raw: { width, height, channels: 3 } }).raw().toBuffer();
