  else if (digits.length === 10) normalized = "1" + digits;
  else normalized = digits;
  return "+" + normalized;
}).filter((value) => /^\\+\\d{10,15}$/.test(value));
console.log(numbers.join("\\n"));
writeFileSync("phones.txt", numbers.join("\\n") + "\\n");
`);
}

