    return;
  }
  await run(
    meta,
    dir,
    "curl",
    ["-L", "-sS", "--max-time", "25", "-A", "Mozilla/5.0", "-o", "oembed.json", `https://www.youtube.com/oembed?url=${encodeURIComponent(url)}&format=json`],
    { timeout: 30000 }
  );
  await run(
    meta,
    dir,
    "curl",
    ["-L", "-sS", "--max-time", "25", "-A", "Mozilla/5.0", "-o", "watch.html", url],
